/**
 * Composes the enrollment flow without persisting credentials.
 * Retained status stays visible, but mutations require capability and live
 * readiness, rechecked on submit. Only confirmed open mode hides controls.
 */
import { useEffect, useRef, useState, useSyncExternalStore } from 'react'
import { onlineManager, useQueryClient } from '@tanstack/react-query'
import { useTranslation } from 'react-i18next'
import { GlassPanel, ConfirmDialog, HelperText, Button } from '@/components/ui'
import { VisuallyHidden } from '@/components/a11y'
import { Skeleton, QueryError } from '@/components/feedback'
import { deriveDataState } from '@/api/dataState'
import { FadeIn } from '@/components/motion'
import { totpKeys, type TOTPStatus } from '@/api/hooks/useTOTP'
import {
  useTotpEnrollmentFlow,
  TotpStatusHero,
  TotpEnrollModal,
  TotpBackupCodesModal,
  TotpOpenModeNotice,
} from './twofactor'

interface TOTPEnrollmentSectionProps {
  capability?: boolean
  liveReady?: boolean
}

const subscribeToOnline = (onChange: () => void) => onlineManager.subscribe(onChange)
const getOnlineSnapshot = () => onlineManager.isOnline()

export function TOTPEnrollmentSection({
  capability = true,
  liveReady = true,
}: TOTPEnrollmentSectionProps = {}) {
  const { t } = useTranslation('settings')
  const queryClient = useQueryClient()
  const flow = useTotpEnrollmentFlow()
  const { status } = flow
  const statusState = deriveDataState(status)
  const online = useSyncExternalStore(subscribeToOnline, getOnlineSnapshot)
  const readiness = useRef({ capability, liveReady })
  readiness.current = { capability, liveReady }
  const [submissionBlocked, setSubmissionBlocked] = useState(false)
  const commandsReady = capability && liveReady && online
    && status.isSuccess && status.fetchStatus === 'idle'
    && status.data?.mode === 'session'
  useEffect(() => {
    if (commandsReady) setSubmissionBlocked(false)
  }, [commandsReady, status.dataUpdatedAt])
  const blockedMessage = t(
    'totp.commands.blocked',
    'Two-factor changes require available enrollment access and a successful live status check. Previously loaded settings remain visible. Retry the status check when access and the connection are ready.',
  )
  const guardCommand = (command: () => void | Promise<void>, expectedActivated: boolean) => () => {
    // Read the cache at submission time too: a dialog may outlive its status read.
    const current = queryClient.getQueryState<TOTPStatus>(totpKeys.status)
    if (!readiness.current.capability || !readiness.current.liveReady
      || !onlineManager.isOnline() || current?.status !== 'success'
      || current.fetchStatus !== 'idle' || current.data?.mode !== 'session'
      || (current.data.activated === true) !== expectedActivated) {
      setSubmissionBlocked(true)
      return
    }
    setSubmissionBlocked(false)
    void command()
  }

  if (statusState.status === 'initial' && !statusState.isRefreshBlocked
    && status.fetchStatus === 'fetching') {
    return (
      <FadeIn delay={0.05}>
        <GlassPanel
          role="status"
          aria-busy="true"
          aria-label={t('totp.loading', 'Loading two-factor settings…')}
          className="flex items-center gap-4 p-4 sm:p-5"
        >
          <Skeleton rounded className="h-11 w-11 shrink-0" />
          <div className="flex-1 space-y-2">
            <Skeleton className="h-5 w-48" />
            <Skeleton className="h-3 w-full max-w-md" />
            <VisuallyHidden>
              {t('totp.loading', 'Loading two-factor settings…')}
            </VisuallyHidden>
          </div>
        </GlassPanel>
      </FadeIn>
    )
  }

  if (statusState.fatalError) {
    return (
      <FadeIn delay={0.05}>
        <GlassPanel className="p-4 sm:p-5">
          <QueryError error={statusState.fatalError} onRetry={() => void status.refetch()} />
        </GlassPanel>
      </FadeIn>
    )
  }

  if (!status.data) {
    return (
      <FadeIn delay={0.05}>
        <GlassPanel className="space-y-3 p-4 sm:p-5" role="status">
          <HelperText>
            {statusState.isRefreshBlocked
              ? t('common:dataSources.status.paused', 'Refresh paused')
              : t('totp.loading', 'Loading two-factor settings…')}
          </HelperText>
          <HelperText>{blockedMessage}</HelperText>
          <Button variant="ghost" onClick={() => void status.refetch()}>
            {t('common:retry', 'Retry')}
          </Button>
        </GlassPanel>
      </FadeIn>
    )
  }

  if (status.data.mode === 'open') {
    return (
      <FadeIn delay={0.05}>
        <TotpOpenModeNotice />
      </FadeIn>
    )
  }

  const sessionStatus = status.data
  const activated = sessionStatus.activated === true
  const lastUsedAt = activated ? sessionStatus.last_used_at : undefined
  const backupRemaining = activated ? sessionStatus.backup_codes_remaining : 0

  return (
    <>
      <FadeIn delay={0.05}>
        {!commandsReady && (
          <div className="space-y-2 pb-3" role="status" data-testid="totp-commands-blocked">
            <HelperText>{blockedMessage}</HelperText>
            <Button variant="ghost" onClick={() => void status.refetch()} disabled={status.isFetching}>
              {t('common:retry', 'Retry')}
            </Button>
          </div>
        )}
        <fieldset disabled={!commandsReady} className="min-w-0">
          <TotpStatusHero
            activated={activated}
            lastUsedAt={lastUsedAt}
            backupRemaining={backupRemaining}
            enrolling={flow.enrolling}
            regenerating={flow.regenerating}
            onEnroll={guardCommand(flow.handleEnroll, false)}
            onRegenerate={guardCommand(flow.handleRegenerate, true)}
            onDisable={guardCommand(flow.openDisableConfirm, true)}
          />
        </fieldset>
      </FadeIn>

      <TotpEnrollModal
        open={flow.dialogStep === 'enroll'}
        enrollment={flow.enrollment}
        code={flow.verifyCode}
        error={!commandsReady || submissionBlocked ? blockedMessage : flow.verifyError}
        verifying={flow.verifying}
        onCodeChange={flow.changeVerifyCode}
        onVerify={guardCommand(flow.handleVerify, false)}
        onClose={flow.closeDialog}
      />

      <TotpBackupCodesModal
        open={flow.dialogStep === 'backupCodes'}
        codes={flow.revealedCodes}
        onDownload={flow.downloadCodes}
        onClose={flow.closeDialog}
      />

      <ConfirmDialog
        open={flow.showDisableConfirm}
        title={t('totp.disable.title', 'Disable two-factor authentication?')}
        message={t(
          'totp.disable.message',
          'You will no longer be prompted for a TOTP code on the sudo step-up. Your backup codes will be invalidated.',
        )}
        confirmLabel={t('totp.disable.confirm', 'Disable')}
        cancelLabel={t('totp.disable.cancel', 'Keep TOTP enabled')}
        variant="danger"
        loading={flow.revoking}
        confirmDisabled={!commandsReady}
        details={!commandsReady || submissionBlocked ? <HelperText>{blockedMessage}</HelperText> : undefined}
        requireTypedConfirmation="DISABLE"
        typedConfirmationLabel={flow.disableTypedLabel}
        onConfirm={guardCommand(flow.handleConfirmDisable, true)}
        onCancel={flow.closeDisableConfirm}
      />
    </>
  )
}

export default TOTPEnrollmentSection

import { type ReactNode } from 'react'
import { useTranslation } from 'react-i18next'

import { GlassPanel, PanelTitle } from '@/components/ui'
import { MetricBar } from '@/components/data-display'
import { Skeleton, EmptyState, QueryError } from '@/components/feedback'
import { useNumberFormatting } from '@/hooks/useNumberFormatting'
import { chartTokens, typography } from '@/lib/tokens'

import type { BreakdownItem } from './sessionStats'

interface SessionBreakdownPanelProps {
  title: string
  /** Decorative leading glyph — rendered aria-hidden. */
  icon: ReactNode
  items: BreakdownItem[]
  /** Total sessions — the denominator for each bar. */
  total: number
  isLoading: boolean
  isError: boolean
  error?: unknown
  onRetry?: () => void
  emptyMessage: string
  /** Offsets into the color-blind-safe series so sibling panels differ. */
  colorOffset?: number
}

/**
 * One device-breakdown panel (by browser / platform / network). Fully
 * self-sufficient: renders its own skeleton, error, and empty states so the
 * page never has to gate the whole bento behind a single condition.
 */
export function SessionBreakdownPanel({
  title,
  icon,
  items,
  total,
  isLoading,
  isError,
  error,
  onRetry,
  emptyMessage,
  colorOffset = 0,
}: SessionBreakdownPanelProps) {
  const { t } = useTranslation()
  const { fmtInt } = useNumberFormatting()
  const series = chartTokens.series
  const rows = items ?? []
  const max = total > 0 ? total : 1

  // Even when the caller flags an error without supplying an error object,
  // surface a retryable failure card so the panel body never collapses to
  // just its title — QueryError renders nothing for a falsy error.
  const shownError =
    isError && !error
      ? new Error(t('account.sessions.breakdownError', 'Failed to load sessions'))
      : error

  return (
    <GlassPanel className="p-4 sm:p-5">
      <PanelTitle className="mb-3 flex items-center gap-2">
        <span className={typography.color.muted} aria-hidden="true">
          {icon}
        </span>
        {title}
      </PanelTitle>
      {isLoading ? (
        <Skeleton height={168} />
      ) : isError ? (
        <QueryError error={shownError} onRetry={onRetry} />
      ) : rows.length === 0 ? (
        <EmptyState
          message={emptyMessage}
          action={onRetry ? { label: t('common.retry', 'Retry'), onClick: onRetry } : undefined}
        />
      ) : (
        <div className="space-y-3">
          {rows.map((row, i) => (
            <MetricBar
              key={row.key}
              label={row.label}
              value={row.count}
              max={max}
              color={series[(i + colorOffset) % series.length]}
              sublabel={fmtInt(row.count)}
            />
          ))}
        </div>
      )}
    </GlassPanel>
  )
}

export default SessionBreakdownPanel

import { useTranslation } from 'react-i18next'
import { ShieldAlert } from 'lucide-react'

import { GlassPanel } from '@/components/ui'
import { EmptyState } from '@/components/feedback'

/**
 * Full-width placeholder shown when the backend reports AUTH_MODE_OPEN — the
 * install runs without a forward-auth header, so per-device sessions can't be
 * tracked. Mirrors the inline placeholder other security primitives render
 * until the `<RequiresAuth capability="session_list">` wrapper ships.
 */
export function SessionsOpenModeNotice() {
  const { t } = useTranslation('settings')

  // Reused for both the visible EmptyState heading and the landmark region's
  // accessible name so a screen-reader user navigating by region lands on a
  // named notice rather than an anonymous "region". Mirrors the
  // `role="region" aria-labelledby={heading}` pattern the drive/charging
  // detail panels use; EmptyState owns the heading so we label by value.
  const title = t('account.sessions.openMode.title', 'Session tracking unavailable')

  return (
    <GlassPanel
      className="p-4 sm:p-5"
      data-testid="active-sessions-open-mode"
      role="region"
      aria-label={title}
    >
      {/* no-action: the fix is a reverse-proxy configuration change (inject X-Forwarded-User) outside this SPA; there is no in-app control that can enable forward-auth mode. */}
      <EmptyState
        icon={<ShieldAlert className="h-8 w-8" aria-hidden="true" />}
        title={title}
        message={t(
          'account.sessions.openMode.message',
          'Active session tracking requires forward-auth mode. Configure your reverse proxy to inject X-Forwarded-User, then reload.',
        )}
      />
    </GlassPanel>
  )
}

export default SessionsOpenModeNotice

import { useCallback, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { LogOut } from 'lucide-react'

import {
  GlassPanel,
  PanelTitle,
  Badge,
  Button,
  DataTable,
  Text,
  type Column,
} from '@/components/ui'
import { Skeleton, QueryError } from '@/components/feedback'
import { useDateFormat } from '@/hooks/useDateFormat'
import type { ActiveSession } from '@/api/types'

import { describeDevice } from './deviceLabel'

interface SessionsTableProps {
  sessions: ActiveSession[]
  /** Opens the per-row revoke confirmation for the given session. */
  onRevoke: (session: ActiveSession) => void
  /** Id of the session whose revoke mutation is in flight (disables its row). */
  revokingId?: string | null
  isLoading: boolean
  isError: boolean
  error?: unknown
  onRetry?: () => void
}

/**
 * Detail band: the full list of active devices with a per-row "Sign out"
 * action. The current device is flagged and never gets a revoke button (you
 * can't sign yourself out here — that's what "sign out all others" is for).
 * Owns its own loading + error states; the empty state is handled by
 * `DataTable`'s `emptyMessage`.
 */
export function SessionsTable({
  sessions,
  onRevoke,
  revokingId,
  isLoading,
  isError,
  error,
  onRetry,
}: SessionsTableProps) {
  const { t } = useTranslation('settings')
  const { formatDateTime } = useDateFormat()

  const columns = useMemo<Column<ActiveSession>[]>(
    () => [
      {
        key: 'device',
        filterValue: (row) => row.user_agent || null,
        filterValueLabel: (_value, row) => describeDevice(row.user_agent),
        header: t('account.sessions.columns.device', 'Device'),
        render: (row) => (
          <div className="flex items-center gap-2">
            <Text color="primary">{describeDevice(row.user_agent)}</Text>
            {row.current ? (
              <Badge
                variant="success"
                size="sm"
                data-testid={`active-sessions-current-pill-${row.id}`}
              >
                {t('account.sessions.current', 'This device')}
              </Badge>
            ) : null}
          </div>
        ),
      },
      {
        key: 'ip',
        filterValue: (row) => row.ip || null,
        header: t('account.sessions.columns.ip', 'IP address'),
        render: (row) => (
          <Text color="secondary" className="tabular-nums">{row.ip || '—'}</Text>
        ),
      },
      {
        key: 'created_at',
        filterValue: (row) => row.created_at ?? null,
        filterValueLabel: (_value, row) => formatDateTime(row.created_at),
        header: t('account.sessions.columns.createdAt', 'Signed in'),
        render: (row) => (
          <Text color="secondary">{formatDateTime(row.created_at)}</Text>
        ),
      },
      {
        key: 'last_seen_at',
        filterValue: (row) => row.last_seen_at ?? null,
        filterValueLabel: (_value, row) => formatDateTime(row.last_seen_at),
        header: t('account.sessions.columns.lastSeenAt', 'Last seen'),
        render: (row) => (
          <Text color="secondary">{formatDateTime(row.last_seen_at)}</Text>
        ),
      },
      {
        key: 'actions',
        header: '',
        align: 'right',
        render: (row) =>
          row.current ? null : (
            <Button
              variant="ghost"
              size="sm"
              className="min-h-11 min-w-11 md:min-h-9"
              onClick={() => onRevoke(row)}
              disabled={revokingId === row.id}
              icon={<LogOut className="h-4 w-4" aria-hidden="true" />}
              data-testid={`active-sessions-revoke-${row.id}`}
              aria-label={t('account.sessions.row.revokeAria', 'Sign out {{device}}', {
                device: describeDevice(row.user_agent),
              })}
            >
              {t('account.sessions.row.revoke', 'Sign out')}
            </Button>
          ),
      },
    ],
    [t, formatDateTime, onRevoke, revokingId],
  )

  // Stable identity so `DataTable`'s internal row-key/selection memos don't
  // recompute on every parent render.
  const keyExtractor = useCallback((row: ActiveSession) => row.id, [])

  return (
    <section className="min-w-0" aria-label={t('account.sessions.tableAria', 'Active devices')}>
      <GlassPanel className="min-w-0 p-4 sm:p-5" data-testid="active-sessions-section">
        <PanelTitle className="mb-3">
          {t('account.sessions.tableTitle', 'Active devices')}
        </PanelTitle>
        {isLoading ? (
          <Skeleton height={240} />
        ) : isError ? (
          <QueryError error={error} onRetry={onRetry} />
        ) : (
          <DataTable<ActiveSession>
            tableId="settings:active-sessions"
            columns={columns}
            name={t('account.sessions.tableAria', 'Active devices')}
            data={sessions ?? []}
            enableValueFilters
            keyExtractor={keyExtractor}
            emptyMessage={t('account.sessions.empty', 'No active sessions for this account.')}
            pagination
          />
        )}
      </GlassPanel>
    </section>
  )
}

export default SessionsTable

/**
 * Backup-codes reveal modal — shown once after enroll or regenerate.
 *
 * The plain-text codes are surfaced a single time; this modal offers
 * copy + download before the user dismisses it. Presentational only —
 * the code list, download handler, and dismissal come from the flow.
 */
import { useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { Download } from 'lucide-react'
import { Modal, Button, Code, Text } from '@/components/ui'
import { EmptyState } from '@/components/feedback'
import { TotpCopyAction } from './TotpCopyAction'

interface TotpBackupCodesModalProps {
  open: boolean
  codes: string[] | null
  onDownload: () => void
  onClose: () => void
}

export function TotpBackupCodesModal({ open, codes, onDownload, onClose }: TotpBackupCodesModalProps) {
  const { t } = useTranslation('settings')

  // Null-safe copy of the list so `.length`/`.map`/`.join` never touch a
  // nullish value, and a stable clipboard payload that only changes when the
  // codes do.
  const list = useMemo(() => codes ?? [], [codes])
  const clipboardText = useMemo(() => list.join('\n'), [list])
  const hasCodes = list.length > 0

  return (
    <Modal
      open={open && codes != null}
      onClose={onClose}
      size="sm"
      title={t('totp.backupCodes.title', 'Save your backup codes')}
      data-testid="totp-backup-modal"
    >
      {codes != null ? (
        <div className="space-y-4">
          {hasCodes ? (
            <>
              <Text variant="bodySm" as="p">
                {t(
                  'totp.backupCodes.warning',
                  'These codes will not be shown again. Store them in a password manager. Each code can be used once if you lose access to your authenticator app.',
                )}
              </Text>
              <ul
                className="grid grid-cols-2 gap-2 rounded-md border border-[var(--border-subtle)] bg-[var(--surface-2)] p-3"
                data-testid="totp-backup-list"
              >
                {list.map((c, i) => (
                  <li key={`${c}-${i}`}>
                    <Code>{c}</Code>
                  </li>
                ))}
              </ul>
              <div className="flex flex-wrap items-center justify-end gap-2">
                {/* flow-cta: saving backup codes is this dialog’s task */}
                <Button
                  type="button"
                  variant="ghost"
                  wrapLabel
                  onClick={onDownload}
                  data-testid="totp-backup-download"
                >
                  <Download className="mr-2 h-4 w-4" aria-hidden="true" />
                  {t('totp.backupCodes.download', 'Download .txt')}
                </Button>
                <TotpCopyAction text={clipboardText} />
                <Button type="button" variant="primary" wrapLabel onClick={onClose} data-testid="totp-backup-done">
                  {t('totp.backupCodes.done', 'I saved them')}
                </Button>
              </div>
            </>
          ) : (
            // Degraded path: the enroll/regenerate response carried no codes.
            // Never render an empty grid with a copy button that copies nothing
            // — surface an actionable empty state and a way out instead.
            <div className="space-y-4" data-testid="totp-backup-empty">
              {/* no-action: the Close button below already gives a way out (dismiss and regenerate from two-factor settings). */}
              <EmptyState
                message={t(
                  'totp.backupCodes.empty',
                  'No backup codes were returned. Close this dialog and regenerate your codes from the two-factor settings.',
                )}
              />
              <div className="flex justify-end">
                <Button
                  type="button"
                  variant="primary"
                  onClick={onClose}
                  data-testid="totp-backup-dismiss"
                >
                  {t('totp.backupCodes.close', 'Close')}
                </Button>
              </div>
            </div>
          )}
        </div>
      ) : null}
    </Modal>
  )
}

export default TotpBackupCodesModal

import { useEffect, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { CopyButton, HelperText } from '@/components/ui'

interface TotpCopyActionProps {
  text: string
}

export function TotpCopyAction({ text }: TotpCopyActionProps) {
  const { t } = useTranslation('settings')
  const [copyFailed, setCopyFailed] = useState(false)

  useEffect(() => {
    setCopyFailed(false)
  }, [text])

  return (
    <div className="min-w-0 max-w-full space-y-1">
      <CopyButton
        text={text}
        onCopy={() => setCopyFailed(false)}
        onCopyError={() => setCopyFailed(true)}
      />
      {copyFailed && (
        <HelperText role="status" className="max-w-prose break-words">
          {t(
            'totp.copy.manualHint',
            'Clipboard unavailable. Select the displayed text and copy it manually.',
          )}
        </HelperText>
      )}
    </div>
  )
}

/**
 * Enroll modal — QR + manual secret + 6-digit verify.
 *
 * Presentational only; the enrollment payload, code value, error, and
 * submit/cancel intent all come from `useTotpEnrollmentFlow`. Retains
 * the original `data-testid` hooks used by the section contract test.
 */
import { useTranslation } from 'react-i18next'
import { Modal, Button, Input, CodeBlock, Text, ErrorText } from '@/components/ui'
import type { TOTPEnrollment } from '@/api/types'
import { TotpCopyAction } from './TotpCopyAction'

interface TotpEnrollModalProps {
  open: boolean
  enrollment: TOTPEnrollment | null
  code: string
  error: string | null
  verifying: boolean
  onCodeChange: (value: string) => void
  onVerify: () => void
  onClose: () => void
}

export function TotpEnrollModal({
  open,
  enrollment,
  code,
  error,
  verifying,
  onCodeChange,
  onVerify,
  onClose,
}: TotpEnrollModalProps) {
  const { t } = useTranslation('settings')

  return (
    <Modal
      open={open && enrollment != null}
      onClose={onClose}
      size="sm"
      title={t('totp.modal.enrollTitle', 'Enable TOTP')}
      data-testid="totp-enroll-modal"
    >
      {enrollment != null ? (
        <div className="space-y-4">
          <Text variant="bodySm" as="p">
            {t(
              'totp.modal.scanInstructions',
              'Scan the QR code with your authenticator app, or enter the secret manually.',
            )}
          </Text>
          <div className="flex justify-center">
            <img
              src={enrollment.qr_data_uri}
              alt={t('totp.modal.qrAlt', 'TOTP QR code')}
              width={224}
              height={224}
              className="rounded-md border border-[var(--border-subtle)] bg-white p-2"
              data-testid="totp-qr"
            />
          </div>
          <CodeBlock
            text={enrollment.secret}
            ariaLabel={t('totp.modal.manualLabel', 'Manual entry secret')}
            heading={<Text variant="label">{t('totp.modal.manualLabel', 'Manual entry secret')}</Text>}
            wrap
            action={<TotpCopyAction text={enrollment.secret} />}
          >
              <span data-testid="totp-secret">
                {enrollment.secret}
              </span>
          </CodeBlock>
          <Input
            type="text"
            inputMode="numeric"
            pattern="[0-9]*"
            value={code}
            onChange={(e) => onCodeChange(e.target.value)}
            // Enter submits the code so keyboard users don't have to tab to
            // the Verify button. Suppressed while a verify is in flight.
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !verifying) {
                e.preventDefault()
                onVerify()
              }
            }}
            label={t('totp.modal.codeLabel', 'Enter the 6-digit code from your app')}
            autoFocus
            data-testid="totp-verify-input"
            disabled={verifying}
          />
          {error ? <ErrorText data-testid="totp-verify-error">{error}</ErrorText> : null}
          <div className="flex flex-wrap items-center justify-end gap-2">
            <Button type="button" variant="ghost" wrapLabel onClick={onClose} disabled={verifying}>
              {t('totp.modal.cancel', 'Cancel')}
            </Button>
            <Button
              type="button"
              variant="primary"
              wrapLabel
              onClick={onVerify}
              loading={verifying}
              data-testid="totp-verify-submit"
            >
              {t('totp.modal.verify', 'Verify and activate')}
            </Button>
          </div>
        </div>
      ) : null}
    </Modal>
  )
}

export default TotpEnrollModal

/**
 * Recovery & good-habits panel.
 *
 * Companion guidance for backup codes and day-to-day TOTP use. Static
 * and always visible so the safety advice is a stable part of the
